/**
 * Real-repository harness — scenario manifest.
 *
 * WHY THIS EXISTS. Across the entire repository history there are zero
 * bot-authored pull requests; every existing eval scenario is synthetic,
 * generated by the same project that grades it. This harness is the first thing
 * that points a product at a repository it did NOT write: a real,
 * permissively-licensed open-source project, cloned at a pinned commit, with a
 * realistic provider change injected as an OpenAPI diff and the impacted call
 * sites recorded in a sealed answer key.
 *
 * This file is pure configuration — repository provenance, licence, the injected
 * change, and where the pieces live. It carries NO answer material (the sealed
 * key lives in `answer-key/` and is loaded only by the grader, after the product
 * has run). The clone lives OUTSIDE this git repo so a staged product can never
 * read its own answer key off disk; `harness.ts` asserts that invariant with the
 * shared isolation guard before anything runs.
 */
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));

/** Repo root of THIS git checkout (the tree that holds the sealed answer key). */
export const REPO_ROOT = resolve(HERE, "..", "..");

/**
 * Where real-repo clones are staged from. Deliberately OUTSIDE this git repo so
 * the answer-key isolation invariant holds. Overridable for CI / other machines
 * via MENDPOINT_REAL_REPO_CLONE_ROOT. This is a distinct variable from
 * MENDPOINT_CORPUS_ROOT (the synthetic corpus) — the two must not be conflated,
 * and this harness never parses the corpus variable.
 */
const cloneRootEnv = process.env.MENDPOINT_REAL_REPO_CLONE_ROOT?.trim();
export const CLONE_ROOT_CONFIGURED =
  cloneRootEnv !== undefined && cloneRootEnv.length > 0;
export const CLONE_ROOT = resolve(
  CLONE_ROOT_CONFIGURED ? cloneRootEnv! : join(REPO_ROOT, "..", "mp-realrepo-clones"),
);

export interface RealRepoManifest {
  /** Stable scenario id; matches the sealed answer key's scenario_id. */
  scenarioId: string;
  /** Upstream repository, recorded for provenance. */
  repoUrl: string;
  /** Exact commit the scenario is pinned to. */
  commit: string;
  /** Licence SPDX id; recorded so we never vendor code that forbids it. */
  license: string;
  /** Directory name the repo clones into under CLONE_ROOT. */
  cloneDirName: string;
  /** Provider slug hint for the Fettler change-intel path. */
  providerSlug: string;
  /** Absolute path to the provider contract BEFORE the injected change. */
  specV1Path: string;
  /** Absolute path to the provider contract AFTER the injected change. */
  specV2Path: string;
  /** Absolute path to the sealed answer key (never reachable by the product). */
  answerKeyPath: string;
}

/**
 * Milestone 1 scenario: OpenAI's own Node quickstart repository, against a
 * provider change modelled on OpenAI superseding Chat Completions with the
 * Responses API (POST /v1/chat/completions removed, POST /v1/responses added).
 */
export const OPENAI_QUICKSTART: RealRepoManifest = {
  scenarioId: "fettler-openai-quickstart-chat-completions-removed",
  repoUrl: "https://github.com/openai/openai-quickstart-node.git",
  commit: "6e6e03496440913a82ccba6f17c2f41caa948c58",
  license: "MIT",
  cloneDirName: "openai-quickstart-node",
  providerSlug: "openai",
  specV1Path: join(HERE, "specs", "openai-chat-completions-v1.json"),
  specV2Path: join(HERE, "specs", "openai-chat-completions-v2.json"),
  answerKeyPath: join(
    HERE,
    "answer-key",
    "GROUND_TRUTH.fettler-openai-quickstart-chat-completions-removed.json",
  ),
};

/** Absolute path the manifest's repository clones into. */
export function clonePathFor(manifest: RealRepoManifest): string {
  return join(CLONE_ROOT, manifest.cloneDirName);
}
